M = [
{"id":"ojeabdest","yol":["Tahâret","Abdest"],"baslik":"Oje, boya ve su geçirmeyen maddeler","ar":"الحائل في الوضوء",
 "hanefi":"Abdest ve gusülde yıkanması farz olan yerlere suyun ulaşması şarttır. Oje, yapıştırıcı, kalın boya, hamur, mum gibi deriye ya da tırnağa suyun ulaşmasını engelleyen tabakalar varken alınan abdest ve gusül geçerli olmaz; önce bunlar giderilir. Kına ve benzeri yalnız renk bırakan maddeler suyun ulaşmasına engel olmadığı için abdeste mani değildir. Tırnak arasındaki kir gibi az ve sakınılması güç şeyler affedilir.",
 "mez":{"maliki":["Aynı","Su geçirmeyen tabaka abdeste engeldir; yalnız renk bırakan madde engel değildir."],
        "safii":["Aynı","Organ üzerindeki su geçirmeyen tabaka giderilmeden abdest sahih olmaz."],
        "hanbeli":["Aynı","Yazı mürekkebi gibi az ve sakınılması güç olan şeyler için ruhsat görenler vardır."]},
 "sebep":"Mezhepler arasında esasta ittifak vardır; ayrılık yalnız affedilen az miktarın ölçüsündedir.",
 "delil":[["ayet","Mâide 5:6","./#5-6","“…Yüzlerinizi ve dirseklere kadar ellerinizi yıkayın…” Yıkamak, suyun deriye ulaşmasıyla gerçekleşir."],
          ["hadis","Ayağında kuru yer kalan kişi",hadis("ارجع فأحسن وضوءك"),"Müslim, Tahâret, 31: Hz. Peygamber ayağında tırnak kadar kuru yer kalan kişiye “Dön, abdestini güzelce al.” buyurdu."]],
 "usul":"Emredilen fiil (gasl: yıkamak) lügat anlamıyla yerine getirilir; suyun ulaşmasını engelleyen şey bulunduğunda fiil gerçekleşmiş olmaz."},
{"id":"disdolgu","yol":["Tahâret","Gusül ve hayız"],"baslik":"Diş dolgusu, kaplama ve gusül","ar":"حشو الأسنان والغسل",
 "hanefi":"Hanefîlere göre gusülde ağza ve buruna su vermek farzdır. Tedavi amacıyla yapılan ve çıkarılması zarar veya güçlük doğuran dolgu, kaplama, köprü ve implant gibi şeyler zaruret sebebiyle gusle engel değildir; altına su ulaşmasa da gusül geçerlidir. Kolayca takılıp çıkarılabilen protezlerin gusülde çıkarılması daha uygundur. Diyanet İşleri Başkanlığının görüşü de bu yöndedir.",
 "mez":{"maliki":["Sorun yok","Gusülde ağza ve buruna su vermek sünnet olduğundan dolgu ve kaplama gusle engel değildir."],
        "safii":["Sorun yok","Ağza ve buruna su vermek sünnettir; dolgu gusle engel değildir."],
        "hanbeli":["Engel değil","Hanbelîlerde de ağız ve buruna su vermek farzdır; zaruret sebebiyle yapılan dolgu affedilir."]},
 "sebep":"Gusülde ağız ve burnun bedenin dışı mı içi mi sayılacağı; zaruretin hükmü hafifletmesi.",
 "delil":[["ayet","Mâide 5:6","./#5-6","“…Eğer cünüpseniz iyice yıkanın (fettahherû).” Mübalağalı yıkama emri."],
          ["ayet","Hac 22:78","./#22-78","“…Dinde size bir güçlük yüklemedi.”"]],
 "usul":"“Zaruretler, yasakları mubah kılar” ve “meşakkat kolaylığı celbeder” kaideleri; cebîre (sargı) üzerine meshe kıyas."},
{"id":"disfircalama","yol":["Oruç","Oruç"],"baslik":"Oruçluyken diş fırçalamak ve misvak","ar":"السواك ومعجون الأسنان للصائم",
 "hanefi":"Oruçluyken misvak kullanmak günün her saatinde sünnettir. Diş macunuyla fırçalamak, macun yutulmadıkça orucu bozmaz; ancak tadının boğaza kaçma ihtimali bulunduğundan mekruhtur. Bu sebeple macunsuz fırçalamak veya fırçalamayı sahura ve iftara bırakmak daha uygundur. Ağızda kalan su ve tükürüğü yutmak orucu bozmaz.",
 "mez":{"maliki":["Misvak caiz","Yaş misvakın tadı boğaza gidebileceğinden mekruh görülmüştür; macunda aynı ihtiyat geçerlidir."],
        "safii":["Zevalden sonra mekruh","Oruçlunun ağız kokusunu gidermemek için öğleden sonra misvak mekruhtur."],
        "hanbeli":["Zevalden sonra mekruh (bir rivayet)","Diğer rivayete göre her vakit sünnettir."]},
 "sebep":"“Oruçlunun ağız kokusu Allah katında misk kokusundan daha hoştur” hadisinin, öğleden sonra misvakı mekruh kılıp kılmadığı.",
 "delil":[["hadis","Oruçluyken misvak",hadis("رأيت النبي صلى الله عليه وسلم ما لا أحصي يتسوك وهو صائم"),"Âmir b. Rebîa: “Hz. Peygamber’i oruçluyken sayamayacağım kadar çok misvak kullanırken gördüm.” (Tirmizî, Savm, 29; Buhârî ta‘lîken)."],
          ["hadis","Oruçlunun ağız kokusu",hadis("لخلوف فم الصائم أطيب عند الله من ريح المسك"),"Buhârî, Savm, 2; Müslim, Sıyâm, 163."]],
 "usul":"Hanefîler misvakı mutlak olarak sünnet sayan hadislerin genelliğiyle amel eder; ağız kokusu hadisinin misvakı yasaklamadığını, oruçlunun faziletini anlattığını söyler."},
{"id":"alkolkolonya","yol":["Tahâret","Sular ve necasetler"],"baslik":"Kolonya, ispirto ve alkollü temizlik maddeleri","ar":"الكحول والكولونيا",
 "hanefi":"Ebû Hanîfe ve Ebû Yûsuf’a göre üzüm ve hurma dışındaki maddelerden elde edilen sarhoş edicilerin necasetinin hükmü şarabınki kadar ağır değildir. Günümüzde kolonya, ispirto ve dezenfektanlarda kullanılan alkol, içki olarak üretilmeyip kimyasal yolla elde edildiği ve uçup gittiği için Diyanet İşleri Başkanlığı bunların bedene veya elbiseye sürülmesini namaza engel görmez. Alkollü maddeleri içmek ise haramdır.",
 "mez":{"maliki":["Hamr necistir","Klasik görüşe göre sarhoş edici sıvılar necistir; günümüz Mâlikî âlimlerinin bir kısmı sanayi alkolünü temiz sayar."],
        "safii":["Hamr necistir","Klasik görüşte sarhoş edici sıvı necistir; günümüz âlimlerinin bir kısmı içki olmayan alkolde ruhsat verir."],
        "hanbeli":["Hamr necistir","Klasik görüş budur; kolonya ve dezenfektan konusunda günümüz âlimleri farklı görüşler bildirmiştir."]},
 "sebep":"Mâide 5:90’daki “rics” kelimesinin maddî (hissî) pisliği mi, manevî pisliği mi ifade ettiği; içki olmayan alkolün hamr hükmüne girip girmediği.",
 "delil":[["ayet","Mâide 5:90","./#5-90","“…İçki, kumar, dikili taşlar ve fal okları şeytan işi birer pislik (rics)tir; bunlardan kaçının.”"]],
 "usul":"Hükmün illeti sarhoş ediciliktir; içilmek için üretilmeyen ve uçucu olan maddede illet bulunmadığından içme yasağının dışındaki hükümlerde (temizlik) hafiflik doğar. Umûmu’l-belvâ da hükmü hafifletir."},
{"id":"kadincami","yol":["Namaz","Vitir, cemaat ve secdeler"],"baslik":"Kadınların camiye gitmesi","ar":"خروج النساء إلى المساجد",
 "hanefi":"Hz. Peygamber kadınların camiye gitmesine izin vermiş ve “Allah’ın kadın kullarını Allah’ın mescitlerinden men etmeyin” buyurmuştur. Sonraki Hanefî âlimleri fitne endişesiyle bunu mekruh görmüştür; bu, zamanın şartlarına bağlı bir hükümdür. Günümüzde kadınların tesettüre ve mescit adabına uyarak cemaate, vaaz ve hutbeye katılmaları caizdir; camilerde onlar için uygun yer ayrılmalıdır. Kadına cuma ve cemaat farz değildir; evde kılması da faziletlidir.",
 "mez":{"maliki":["Caiz","Yaşlı kadın gidebilir; genç kadın fitne yoksa farz namazlar ve bayram için gidebilir."],
        "safii":["Caiz","Dikkat çekmeyen kadınlar için caiz; genç ve süslü kadınlar için mekruh."],
        "hanbeli":["Mubah","Kocasının izniyle, süslenmeden ve koku sürünmeden gidebilir."]},
 "sebep":"İzin hadisi ile “Kadının evinde kıldığı namaz daha faziletlidir” hadisinin birlikte değerlendirilmesi ve fitne endişesinin zamana göre değişmesi.",
 "delil":[["hadis","“Allah’ın kadın kullarını Allah’ın mescitlerinden men etmeyin.”",hadis("لا تمنعوا إماء الله مساجد الله"),"Buhârî, Cum‘a, 13; Müslim, Salât, 136."],
          ["hadis","Hz. Âişe’nin sözü",hadis("لو أدرك رسول الله صلى الله عليه وسلم ما أحدث النساء لمنعهن المسجد"),"Buhârî, Ezan, 163; Müslim, Salât, 144."]],
 "usul":"Sedd-i zerâi‘ (kötülüğe giden yolu kapama) ile verilen hükümler, sebep ortadan kalkınca değişir: “Zamanın değişmesiyle hükümlerin değişmesi inkâr edilemez.”"},
{"id":"dovme","yol":["Tahâret","Gusül ve hayız"],"baslik":"Dövme yaptırmak ve abdest-gusül","ar":"الوشم والطهارة",
 "hanefi":"Kalıcı dövme yaptırmak, Allah’ın yaratılışını değiştirme ve bedene zarar verme sebebiyle haramdır. Ancak yapılmış bir dövme deri altında kaldığından suyun deriye ulaşmasına engel değildir; abdest ve gusül geçerlidir. Çıkarılması zarar vermeyecekse çıkartılması, aksi hâlde tövbe edilmesi yeterlidir.",
 "mez":{"maliki":["Haram","Abdest ve gusle engel değildir."],
        "safii":["Haram","Zarar vermeden çıkarılabiliyorsa çıkarılması gerekir; aksi hâlde tövbe yeter."],
        "hanbeli":["Haram","Abdest ve gusle engel değildir."]},
 "sebep":"Dövmenin hükmünde ittifak vardır; ayrılık, çıkarılmasının gerekip gerekmediğindedir.",
 "delil":[["hadis","Dövme yapan ve yaptırana lanet",hadis("لعن الله الواشمات والمستوشمات"),"Buhârî, Libâs, 82; Müslim, Libâs, 120."]],
 "usul":"Haram bir fiilin sonucu, ibadetin şartı olan temizliği etkilemez; şart (suyun deriye ulaşması) gerçekleştiği sürece ibadet sahihtir."},
]
